// The character builder: its rules data (generated by scripts/gen_builder_data.py) and the player's draft.
import type { Ability } from "../rules";
import type { Answers } from "../levelup/types";

export type Rules = "2014" | "2024";
export type Text = { name: string; text: string };

/** One item in a starting kit; `ac`/`armor` for armor, `w` for weapons (to show AC and attacks before saving). */
export type KitItem = {
  name: string; qty: number; ref?: string;
  ac?: { base: number; dex: boolean; max?: number }; armor?: "Light" | "Medium" | "Heavy" | "Shield" | "";
  w?: { damage: string; type: string; props: string[]; ranged: boolean; range?: string };
};
export type CategoryItem = Omit<KitItem, "qty">;
/** "Pick 1 martial weapon" inside a kit. */
export type KitPick = { category: string; choose: number; label: string };
export type Kit = { label: string; items: KitItem[]; gp: number; picks: KitPick[] };
/** Choose one kit of the group: "(a) chain mail or (b) leather armor, longbow and 20 arrows". */
export type KitGroup = { desc: string; options: Kit[] };

export type ClassBuild = {
  primary: string | null; proficiencies: string[]; skills: { choose: number; from: string[] } | null;
  equipmentFixed: KitItem[]; equipment: KitGroup[];
};
export type SpeciesSub = { name: string; traits: Text[]; asi?: { a: Ability; b: number }[] };
export type SpeciesData = {
  name: string; speed: number; size: string; traits: Text[]; asi: { a: Ability; b: number }[];
  asiChoice?: { choose: number; bonus: number; from: Ability[] }; languages?: string; subs: SpeciesSub[];
};
export type BackgroundData = {
  name: string; skills: string[]; tools: string[];
  // 2024
  abilities?: Ability[]; feat?: { name: string; note: string | null } | null;
  // 2014
  languages?: number; equipmentFixed?: KitItem[]; gp?: number; feature?: Text | null; tables?: Record<string, string[]>;
  equipment: KitGroup[];
};
export type BuilderData = {
  rules: Rules; source: string;
  classes: Record<string, ClassBuild>;
  species: SpeciesData[];
  backgrounds: BackgroundData[];
  categories: Record<string, { name: string; items: CategoryItem[] }>;
  languages: string[];
};

export type ScoreMethod = "standard" | "pointbuy" | "roll" | "manual";
/** 2024 backgrounds: +2/+1 to two of its three abilities, or +1 to all three. */
export type BgAsi = { mode: "2-1"; plus2: Ability; plus1: Ability } | { mode: "1-1-1" };
/** Kit choices: for each group the kit taken, and for each "pick" in it the items chosen (refs or names). */
export type KitChoice = { option: number; picks: string[][] };
/** Choices a feat asks for (Magic Initiate: a spell list, 2 cantrips, a 1st-level spell, an ability; Skilled: 3 skills). */
export type FeatChoice = { list?: string; cantrips?: string[]; spell?: string; ability?: Ability; skills?: string[] };

export type Draft = {
  rules: Rules;
  cls: string;
  species: string;
  sub: string | null;
  /** species extras: skills (Skillful, Keen Senses, Skill Versatility), an origin feat (Versatile), a cantrip (High Elf), the lineage's spell ability, +1s (Half-Elf) */
  speciesPicks: { skills: string[]; feat: string | null; cantrip: string | null; ability: Ability | null; asi: Ability[] };
  background: string; // a background's name, or "Other"
  customBackground: { name: string; abilities: Ability[]; feat: string | null; skills: string[] };
  bgAsi: BgAsi;
  languages: string[];
  method: ScoreMethod;
  base: Record<Ability, number>;
  classSkills: string[];
  feats: Record<string, FeatChoice>; // by feat name
  level: Answers;                    // the level-1 choices from the level-up engine (subclass, fighting style, mastery, cantrips, spells…)
  kit: KitChoice[];
  bgKit: KitChoice[];
  details: { name: string; playerName: string; alignment: string; personality: string; ideals: string; bonds: string; flaws: string; backstory: string };
  targetLevel: number;
  forMe: boolean;
};
